import (
	"net/url"
	"strings"
)

/**
Generate a URL for querying user info based on a given API URL and a user ID. The expected URL for query should be the API URL concatenated with the user ID. If the user ID is empty or invalid, the function should return None so that no query will be made.
Examples:
- getURLForQuery("https://example.com/api/user", "aBc123") returns 'https://example.com/api/user/aBc123'
- getURLForQuery("https://example.com/api/user", "") returns NULL

@param api_url: The API URL to query user info.
@param user_id: The user ID to query.

@return The URL for query. If the user ID is empty or invalid, return NULL.
*/
func getURLForQuery(apiURL, userID string) *string {
	// As per the examples and description, an empty user ID is considered invalid.
	// If there were other criteria for "invalid", they would be added here.
	if userID == "" {
		return nil // Return nil (Go's equivalent of NULL) for an empty user ID.
	}

	// Ensure the API URL does not end with a slash to prevent double slashes
	// when concatenating with the user ID. For example, "api/user/" + "/id" -> "api/user//id".
	// By trimming, "api/user/" becomes "api/user".
	trimmedAPIURL := strings.TrimSuffix(apiURL, "/")

	// URL-encode the user ID to ensure it's safe to be part of a URL path.
	// This prevents issues with special characters (e.g., spaces, '/', '?', '&', '#')
	// that would otherwise make the URL malformed or lead to unintended interpretation
	// by the HTTP client or server. It also mitigates potential URL injection vulnerabilities.
	encodedUserID := url.PathEscape(userID)

	// Construct the full query URL by appending a single slash and the encoded user ID.
	fullURL := trimmedAPIURL + "/" + encodedUserID

	// Return a pointer to the constructed URL string.
	return &fullURL
}
